using System.Collections;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "RestorationBurstAction", menuName = "Data/Battle/Battle Actions/Hevelius/RestorationBurst Action")]
public class RestorationBurstAction : BattleAction
{
	[Header("Sacrifice Companion Action")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	[SerializeField]
	protected BattleAction battleAction;

	[SerializeField]
	private OmenLogic omenLogic;

	[SerializeField]
	private float vfxDelay;

	[SerializeField]
	private float purifyDelay;

	public BattleAction BattleAction => battleAction;

	public override bool CheckCondition(GameObject target, int actionValue)
	{
		return target.GetComponent<CorruptionStats>().CurrentCorruption > 0f;
	}

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		List<GameObject> activeCompanions = currentCompanions.ActiveCompanions;
		if (activeCompanions.Count > 0)
		{
			for (int i = 0; i < activeCompanions.Count; i++)
			{
				if (activeCompanions[i].GetComponent<CorruptionStats>().GetCorruptionPercentage() > 0f)
				{
					return true;
				}
			}
		}
		return false;
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(RestorationBurstCoroutine(target, amount, source));
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
	}

	private IEnumerator RestorationBurstCoroutine(GameObject target, int amount, GameObject source)
	{
		if (IsVFXEnabled())
		{
			PlaySFX();
			SpawnVFX(GetVFXOwnerPosition(target));
			yield return new WaitForSeconds(vfxDelay);
		}
		CompanionCorruptionStats component = target.GetComponent<CompanionCorruptionStats>();
		int amount2 = (int)component.CurrentCorruption;
		int amountToDealPurify = component.Purify(amount2, source, CorruptionPurifyModifierEnum.PIERCE);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		if (IsVFXEnabled())
		{
			yield return new WaitForSeconds(purifyDelay);
		}
		omenLogic.ActivateOmen(battleAction, amount * amountToDealPurify, target, source);
	}
}
